import type { ReactElement } from 'react';
import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export const STATUS_LABELS = {
  active: 'Active',
  idle: 'Idle',
  error: 'Error',
  offline: 'Offline',
} as const satisfies Record<Status, string>;

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'active':
      return 'status-active';
    case 'idle':
      return 'status-idle';
    case 'error':
      return 'status-error';
    case 'offline':
      return 'status-offline';
  }
}

function groupByStatus(items: StatusItem[]): Map<Status, StatusItem[]> {
  const groups = new Map<Status, StatusItem[]>();
  for (const item of items) {
    const existing = groups.get(item.status) ?? [];
    existing.push(item);
    groups.set(item.status, existing);
  }
  return groups;
}

interface StatusListProps {
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): ReactElement {
  if (items === null) {
    return (
      <ul className="status-list status-list--loading" role="list">
        {Array.from({ length: SKELETON_COUNT }).map((_, i) => (
          <li key={i} className="status-list-item status-list-item--skeleton">
            <span className="status-list-skeleton-bar" />
            <span className="status-list-skeleton-label" />
          </li>
        ))}
      </ul>
    );
  }

  const groups = groupByStatus(items);

  return (
    <div className="status-list-container">
      {Array.from(groups.entries()).map(([status, groupItems]) => (
        <section key={status} className="status-list-group">
          <h3 className="status-list-group-heading">{STATUS_LABELS[status]}</h3>
          <ul className="status-list" role="list">
            {groupItems.map((item) => (
              <li key={item.id} className={`status-list-item ${statusColor(item.status)}`}>
                <span className="status-list-item-label">{item.label}</span>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}
